#[derive(Debug, Clone, PartialEq, Eq)]
pub enum DateTime64 {
    Nat,
    Valid(i64),
}

pub fn isnat(x: Vec<DateTime64>) -> Vec<bool> {
    x.into_iter()
     .map(|dt| matches!(dt, DateTime64::Nat))
     .collect()
}

